mapper.select:
select s.serviceid as serviceid, s.codebid as codebid, s.name as name, s.price as price, s.isactive as isactive, s.servicevalue as servicevalue, s.createdat as createdat, s.updatedat as updatedat, s.note as note from service s where s.isactive = 1
and lower(s.name) like concat('%', lower(#{keyword}), '%')
and s.codebid in
#{code}
order by case when s.codebid like '%PT%' then 0 else 1 end, s.name desc limit #{endRowNum} offset #{startRowNum}

select p.productid, p.codebid, p.name, p.price, p.isactive from product p where p.isactive = 1
and upper(p.name) like concat('%', upper(#{keyword}), '%')
order by p.name desc limit #{endRow} offset #{startRow}

select e.empnum as empnum, e.empname as empname, e.empemail as empemail from employee e where e.firedate is null
and ( upper(e.empname) like concat('%', upper(#{keyword}), '%') or upper(e.empemail) like concat('%', upper(#{keyword}), '%') )
order by e.empname asc limit #{endRow} offset #{startRow}
